]];

rumMicroBench[label_String, nExpr_, expr_] := Module[
  {i, k, n, seconds, best},
  n = nExpr;
  rumMicroSink = expr;
  best = -1;
  k = 1;
  While[k <= rumMicroReps,
    seconds = First[AbsoluteTiming[
      Do[
        expr,
        {i, 1, n}
      ]
    ]];
    If[best < 0 || seconds < best, best = seconds];
    k = k + 1
  ];
  rumMicroEmit[label, n, best];
];

