pub(crate) fn eval_string_trim(
    session: &mut Session,
    head: &Expr,
    args: &SharedArgs,
) -> Result<Expr, EvalError> {
    let args = args.as_ref();
    if !(1..=2).contains(&args.len()) {
        return Ok(session.invalid_call_with_arg_range("StringTrim", args, 1, 2));
    }

    let trim_spec = match args.get(1) {
        Some(expr) => parse_string_boundary_spec(expr),
        None => Some(StringBoundarySpec::Whitespace),
    };
    let Some(trim_spec) = trim_spec else {
        return Ok(Expr::call(head.clone(), args.to_vec()));
    };

    if let Some(value) = expr_as_string(&args[0]) {
        return Ok(Expr::string(trim_string_value(value, &trim_spec)));
    }

    if let Some(values) = expr_as_string_list(&args[0]) {
        return Ok(string_list_expr(
            values
                .into_iter()
                .map(|value| trim_string_value(&value, &trim_spec))
                .collect(),
        ));
    }

    Ok(Expr::call(head.clone(), args.to_vec()))
}

pub(in crate::strings::patterns) fn trim_string_value(
    value: &str,
    spec: &StringBoundarySpec,
) -> String {
    let chars = value.chars().collect::<Vec<_>>();
    match spec {
        StringBoundarySpec::Whitespace => trim_whitespace_chars(&chars),
        StringBoundarySpec::Patterns(patterns) => trim_string_patterns(&chars, patterns),
    }
}

pub(super) fn trim_whitespace_chars(chars: &[char]) -> String {
    let mut start = 0usize;
    let mut end = chars.len();

    while start < end && is_string_whitespace(chars[start]) {
        start += 1;
    }
    while start < end && is_string_whitespace(chars[end - 1]) {
        end -= 1;
    }

    chars[start..end].iter().collect()
}

pub(super) fn trim_string_patterns(chars: &[char], patterns: &[StringPattern]) -> String {
    if let [pattern] = patterns {
        if let Some(literal) = exact_literal_pattern(pattern, StringPatternMatchConfig::default()) {
            return trim_literal(chars, literal);
        }
    }

    if patterns.iter().all(|pattern| {
        exact_literal_pattern(pattern, StringPatternMatchConfig::default()).is_some()
    }) {
        #[cfg(test)]
        LITERAL_TRIM_FAST_PATH_CALLS.set(LITERAL_TRIM_FAST_PATH_CALLS.get() + 1);
        return trim_literal_patterns(chars, patterns);
    }

fn trim_literal(chars: &[char], literal: &[char]) -> String {
    let mut start = 0usize;
    let mut end = chars.len();

    while start < end && chars[start..end].starts_with(literal) {
        start += literal.len();
    }
    while start < end && chars[start..end].ends_with(literal) {
        end -= literal.len();
    }

    chars[start..end].iter().collect()
}

fn trim_literal_patterns(chars: &[char], patterns: &[StringPattern]) -> String {
    let mut start = 0usize;
    let mut end = chars.len();

    while start < end {
        let Some(length) = longest_matching_literal_length(patterns, |literal| {
            chars[start..end].starts_with(literal)
        }) else {
            break;
        };
        start += length;
    }
    while start < end {
        let Some(length) = longest_matching_literal_length(patterns, |literal| {
            chars[start..end].ends_with(literal)
        }) else {
            break;
        };
        end -= length;
    }

}

pub(super) fn normalize_call_args_by_attributes(
    &self,
    head: &Expr,
    args: Vec<Expr>,
    attributes: AttributeSet,
) -> Vec<Expr> {
    let runtime_profile_total = runtime_path_timing_start("prepare_arguments.normalize.total");
    let mut normalized_args = if attributes.contains(Attribute::Flat) {
        let runtime_profile_flat =
            runtime_path_timing_start("prepare_arguments.normalize.flat");
        let result = flatten_flat_call_args(head, args);
        record_profile_runtime_path_timing(runtime_profile_flat, RuntimeProfileOutcome::Ok);
        result
    } else {
        args
    };
